CREATE TABLE suppliers (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, supplier_code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, category VARCHAR(255) NOT NULL, country VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, risk_level VARCHAR(255) NOT NULL);
CREATE TABLE parts (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, part_number VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, category VARCHAR(255) NOT NULL, specification TEXT NOT NULL, status VARCHAR(255) NOT NULL);
CREATE TABLE vehicle_models (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, model_code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, platform VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL);
CREATE TABLE supplier_parts (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, supplier_id VARCHAR(36) NOT NULL, part_id VARCHAR(36) NOT NULL, supplier_part_number VARCHAR(255) NOT NULL, lead_time_days INT NOT NULL, status VARCHAR(255) NOT NULL, UNIQUE(supplier_id,part_id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id), FOREIGN KEY(part_id) REFERENCES parts(id));
CREATE TABLE bom_items (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, vehicle_model_id VARCHAR(36) NOT NULL, part_id VARCHAR(36) NOT NULL, quantity DECIMAL(12,3) NOT NULL, bom_version VARCHAR(255) NOT NULL, effective_from DATE NOT NULL, effective_to DATE, UNIQUE(vehicle_model_id,part_id,bom_version,effective_from), FOREIGN KEY(vehicle_model_id) REFERENCES vehicle_models(id), FOREIGN KEY(part_id) REFERENCES parts(id));
CREATE TABLE batches (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, batch_number VARCHAR(80) NOT NULL UNIQUE, part_id VARCHAR(36) NOT NULL, supplier_id VARCHAR(36) NOT NULL, manufactured_at TIMESTAMP(6) NOT NULL, received_at TIMESTAMP(6), quantity INT NOT NULL, status VARCHAR(255) NOT NULL, FOREIGN KEY(part_id) REFERENCES parts(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
CREATE TABLE inspection_records (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, inspection_number VARCHAR(255) NOT NULL UNIQUE, batch_id VARCHAR(36) NOT NULL, inspection_type VARCHAR(255) NOT NULL, metric_name VARCHAR(255) NOT NULL, measured_value DECIMAL(18,6) NOT NULL, lower_limit DECIMAL(18,6) NOT NULL, upper_limit DECIMAL(18,6) NOT NULL, result VARCHAR(255) NOT NULL, inspected_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(batch_id) REFERENCES batches(id));
CREATE TABLE quality_issues (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, issue_number VARCHAR(255) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, severity VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, detected_at TIMESTAMP(6) NOT NULL, source VARCHAR(255) NOT NULL);
CREATE TABLE quality_issue_batches (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, quality_issue_id VARCHAR(36) NOT NULL, batch_id VARCHAR(36) NOT NULL, UNIQUE(quality_issue_id,batch_id), FOREIGN KEY(quality_issue_id) REFERENCES quality_issues(id), FOREIGN KEY(batch_id) REFERENCES batches(id));
CREATE TABLE quality_cases (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, case_number VARCHAR(255) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, priority VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, owner VARCHAR(255) NOT NULL, opened_at TIMESTAMP(6) NOT NULL, closed_at TIMESTAMP(6));
CREATE TABLE quality_case_issues (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, quality_case_id VARCHAR(36) NOT NULL, quality_issue_id VARCHAR(36) NOT NULL, UNIQUE(quality_case_id,quality_issue_id), FOREIGN KEY(quality_case_id) REFERENCES quality_cases(id), FOREIGN KEY(quality_issue_id) REFERENCES quality_issues(id));
CREATE TABLE corrective_actions (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, action_number VARCHAR(255) NOT NULL UNIQUE, quality_case_id VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, action_type VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, assignee VARCHAR(255) NOT NULL, due_date DATE NOT NULL, correlation_id VARCHAR(255) NOT NULL, FOREIGN KEY(quality_case_id) REFERENCES quality_cases(id));
CREATE TABLE documents (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, document_number VARCHAR(255) NOT NULL, title VARCHAR(255) NOT NULL, document_type VARCHAR(255) NOT NULL, version VARCHAR(255) NOT NULL, source_uri VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, UNIQUE(document_number,version));
CREATE TABLE audit_events (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, actor_type VARCHAR(255) NOT NULL, actor VARCHAR(255) NOT NULL, action VARCHAR(255) NOT NULL, entity_type VARCHAR(255) NOT NULL, entity_id VARCHAR(255) NOT NULL, arguments TEXT NOT NULL, result TEXT NOT NULL, correlation_id VARCHAR(255) NOT NULL);
CREATE TABLE outbox_events (id VARCHAR(36) PRIMARY KEY, record_version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, event_type VARCHAR(255) NOT NULL, aggregate_type VARCHAR(255) NOT NULL, aggregate_id VARCHAR(255) NOT NULL, payload TEXT NOT NULL, correlation_id VARCHAR(255) NOT NULL, published_at TIMESTAMP(6));
CREATE INDEX idx_outbox_unpublished ON outbox_events(published_at,created_at);
CREATE INDEX idx_audit_entity ON audit_events(entity_id,created_at);
